head.script:
scwin.gVar = {
    "cLabel" : "",
    "cLocaleRef" : "",
    "cUseLocale" : "",
}



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[searchbox > M > setRef]<br/>SearchBox 컴포넌트의 ref 속성을 설정합니다.",
    "validation" : [
        "ref(필수) 파라미터로 접근 가능한 DataCollection 의 컬럼을 'data:[DataCollection ID].[Key 또는 Column ID]' 형식으로 설정합니다.",
        "형식에 맞지 않거나 접근할 수 없는 DataCollection 이면 적용되지 않습니다.",
        "메소드가 실행되어 ref 속성이 설정되면 기존 입력값은 사라집니다.",
        "DataList 를 바인딩 한 경우 DataList 의 데이터를 선택하지 않으면 입력창에 빈값이 표시됩니다.",
        "데이터를 선택하지 않은 상태에서 입력된 값은 데이터 선택 시 사라집니다.",
    ]
}



scwin.wf_sample_onwframeload = function () {
    // 테스트 설명, 유효성 생성
    let wf_body_left = wf_sample.getObj("wf_body_left");
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // wframe 의 btn_getText_onclick 을 searchbox 용으로 override
    // (wframe 기본 핸들러는 target1.render.tagName 으로 input/textarea 분기 → searchbox 는 wrapper DOM 이라 INPUT 이 아니어서 textContent 빈값 반환됨)
    wf_sample.getObj("scwin").btn_getText_onclick = function (e) {
        wf_sample.getObj("wf_body_bottom").getObj("scwin").setReturnValue("text : " + target1.getValue());
    };
};



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        // label: scwin.gVar["cLabel"],
        // localeRef: scwin.gVar["cLocaleRef"],
        // useLocale: scwin.gVar["cUseLocale"],
        style: "width:200px;height:30px",
    };

    let cList = $c.gcm.createCList(properties);

    // comp 생성 함수 호출 (searchbox 는 비동기 plugin → await 필수)
    await $c.gcm.createEmptySearchBox(cList);

    wf_sample.getObj("con_label").setDisabled(true);
    wf_sample.getObj("con_localeRef").setDisabled(true);
    wf_sample.getObj("con_useLocale").setDisabled(true);
}
